var minWindow = function(s, t) {
    if (!t || !s) return "";
    const need = {};
    for (const ch of t) need[ch] = (need[ch] || 0) + 1;
    let missing = t.length;
    let left = 0, bestLen = Infinity, bestLeft = 0;
    for (let right = 0; right < s.length; right++) {
        const ch = s[right];
        if ((need[ch] || 0) > 0) missing--;
        need[ch] = (need[ch] || 0) - 1;
        if (missing === 0) {
            while (need[s[left]] < 0) {
                need[s[left]]++;
                left++;
            }
            if (right + 1 - left < bestLen) {
                bestLen = right + 1 - left;
                bestLeft = left;
            }
            need[s[left]]++;
            missing++;
            left++;
        }
    }
    return bestLen === Infinity ? "" : s.slice(bestLeft, bestLeft + bestLen);
};

solution.python:
from collections import Counter

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not t or not s:
            return ""

        need = Counter(t)
        missing = len(t)
        left = 0
        best_length = float("inf")
        best_left = 0

        for right, ch in enumerate(s, 1):
            if need[ch] > 0:
                missing -= 1
            need[ch] -= 1

            if missing == 0:
                while need[s[left]] < 0:
                    need[s[left]] += 1
                    left += 1

                if right - left < best_length:
                    best_length = right - left
                    best_left = left

                need[s[left]] += 1
                missing += 1
                left += 1

        if best_length == float("inf"):
            return ""
        return s[best_left:best_left + best_length]
